    17→export function registerAccountCommand(program: Command): void {
    18→  const account = program
    19→    .command("account")
    20→    .description("Trading account management");
    21→
    22→  account
    23→    .command("list")
    24→    .description("List all trading accounts")
    25→    .action(async () => {
    26→      try {
    27→        const result = await listAccounts();
    28→        if (!result.success) throw CliError.operationFailed("account list", result.error!);
    29→        if (result.accounts.length === 0) {
    30→          console.log("No trading accounts configured. Use 'viben account add' to add one.");
    31→          return;
    32→        }
    33→        console.log("\nTrading Accounts:\n");
    34→        for (const acc of result.accounts) {
    35→          console.log(`  ${chalk.dim(acc.id)}  ${acc.exchange.padEnd(10)} ${acc.name}`);
    36→        }
    37→        console.log(`\nTotal: ${result.accounts.length}`);
    38→      } catch (e) {
    39→        if (e instanceof CliError) { console.error(chalk.red(e.message)); process.exit(1); }
    40→        throw e;
    41→      }
    42→    });
    43→
    44→  account
    45→    .command("add")
    46→    .description("Add a new trading account")
    47→    .option("-e, --exchange <exchange>", "Exchange ID (okx, binance, bitget, bybit, gate, kucoin, lighter)")
    48→    .option("-n, --name <name>", "Account name")
    49→    .option("--api-key <key>", "API key")
    50→    .option("--secret <secret>", "API secret")
    51→    .option("--passphrase <passphrase>", "Passphrase (for OKX/Bitget/KuCoin)")
    52→    .action(async (opts) => {
    53→      try {
    54→        let { exchange, name } = opts;
    55→        const apiKey = opts.apiKey as string | undefined;
    56→        const secret = opts.secret as string | undefined;
    57→        const passphrase = opts.passphrase as string | undefined;
    58→
    59→        if (!exchange || !apiKey || !secret) {
    60→          const exchanges = listExchanges();
    61→          console.log("\nAvailable exchanges:");
    62→          for (const ex of exchanges) {
    63→            console.log(`  ${ex.id.padEnd(10)} ${ex.name}`);
    64→          }
    65→          throw CliError.operationFailed("account add",
    66→            "Non-interactive usage: viben account add --exchange <id> --name <name> --api-key <key> --secret <secret> [--passphrase <pp>]");
    67→        }
    68→
    69→        if (!name) {
    70→          const ex = listExchanges().find((e) => e.id === exchange);
    71→          name = `${ex?.name ?? exchange} #1`;
    72→        }
    73→
    74→        const result = await addAccount({
    75→          exchange: exchange as ExchangeId,
    76→          name,
    77→          api_key: apiKey,
    78→          secret,
    79→          passphrase,
    80→        });
    81→
    82→        if (!result.success) throw CliError.operationFailed("account add", result.error!);
    83→        console.log(chalk.green(`Account added: ${result.account!.name} (${result.account!.id})`));
    84→      } catch (e) {
    85→        if (e instanceof CliError) { console.error(chalk.red(e.message)); process.exit(1); }
    86→        throw e;
    87→      }
    88→    });
    89→
    90→  account
    91→    .command("view <idOrName>")
    92→    .description("View account details (credentials masked)")
    93→    .action(async (idOrName: string) => {
    94→      try {
    95→        const result = await viewAccount(idOrName);
    96→        if (!result.success) throw CliError.operationFailed("account view", result.error!);
    97→        const acc = result.account!;
    98→        console.log(`\n  ID:       ${acc.id}`);
    99→        console.log(`  Exchange: ${acc.exchange}`);
   100→        console.log(`  Name:     ${acc.name}`);
   101→        console.log(`  Created:  ${acc.created_at}`);
   102→        console.log(`  Updated:  ${acc.updated_at}`);
   103→        if (result.masked_credentials) {
   104→          console.log("\n  Credentials:");
   105→          for (const [field, masked] of Object.entries(result.masked_credentials)) {
   106→            console.log(`    ${field}: ${masked}`);
   107→          }
   108→        }
   109→      } catch (e) {
   110→        if (e instanceof CliError) { console.error(chalk.red(e.message)); process.exit(1); }
   111→        throw e;
   112→      }
   113→    });
