   118→    .option("-n, --name <name>", "New account name")
   119→    .option("--api-key <key>", "New API key")
   120→    .option("--secret <secret>", "New API secret")
   121→    .option("--passphrase <passphrase>", "New passphrase")
   122→    .action(async (idOrName: string, opts) => {
   123→      try {
   124→        const result = await updateAccount(idOrName, {
   125→          name: opts.name,
