     3→import type { FastifyInstance, FastifyRequest } from "fastify";
     4→import {
     5→  listAccounts,
     6→  addAccount,
     7→  viewAccount,
     8→  updateAccount,
     9→  removeAccount,
    10→  testAccount,
    11→  listExchanges,
    12→} from "../../account";
    13→import type { ExchangeId } from "../../account";
    14→
    15→interface CreateAccountBody {
    16→  exchange: ExchangeId;
    17→  name: string;
    18→  api_key: string;
    19→  secret: string;
    20→  passphrase?: string;
    21→}
    22→
    23→interface UpdateAccountBody {
    24→  name?: string;
    25→  api_key?: string;
    26→  secret?: string;
    27→  passphrase?: string;
    28→}
    29→
    30→export function registerAccountsRoutes(fastify: FastifyInstance): void {
    31→  // GET /api/exchanges — exchange registry (static meta)
    32→  fastify.get("/api/exchanges", async () => {
    33→    const exchanges = listExchanges();
    34→    return {
    35→      exchanges: exchanges.map((ex) => ({
    36→        id: ex.id,
    37→        name: ex.name,
    38→        fields: ex.fields,
    39→        referral_url: ex.referral_url,
    40→        api_doc_url: ex.api_doc_url,
    41→        whitelist_ip: ex.whitelist_ip,
    42→      })),
    43→    };
    44→  });
    45→
    46→  // GET /api/accounts — list all (no credentials)
    47→  fastify.get("/api/accounts", async () => {
    48→    const result = await listAccounts();
    49→    return result;
    50→  });
    51→
    52→  // POST /api/accounts — create
    53→  fastify.post("/api/accounts", async (
    54→    req: FastifyRequest<{ Body: CreateAccountBody }>,
    55→    reply,
    56→  ) => {
    57→    const { exchange, name, api_key, secret, passphrase } = req.body;
    58→    if (!exchange || !name || !api_key || !secret) {
    59→      reply.code(400);
    60→      return { success: false, error: "exchange, name, api_key, and secret are required" };
    61→    }
    62→    const result = await addAccount({ exchange, name, api_key, secret, passphrase });
    63→    if (!result.success) {
    64→      reply.code(400);
    65→      return result;
    66→    }
    67→    reply.code(201);
    68→    return result;
    69→  });
    70→
    71→  // GET /api/accounts/:id — view (masked credentials)
    72→  fastify.get("/api/accounts/:id", async (
    73→    req: FastifyRequest<{ Params: { id: string } }>,
    74→    reply,
    75→  ) => {
    76→    const result = await viewAccount(req.params.id);
    77→    if (!result.success) {
    78→      reply.code(404);
    79→      return result;
    80→    }
    81→    return result;
    82→  });
    83→
    84→  // PUT /api/accounts/:id — update credentials
    85→  fastify.put("/api/accounts/:id", async (
    86→    req: FastifyRequest<{ Params: { id: string }; Body: UpdateAccountBody }>,
    87→    reply,
    88→  ) => {
    89→    const result = await updateAccount(req.params.id, req.body);
    90→    if (!result.success) {
    91→      reply.code(result.error?.includes("not found") ? 404 : 400);
    92→      return result;
    93→    }
    94→    return result;
    95→  });
    96→
    97→  // DELETE /api/accounts/:id
    98→  fastify.delete("/api/accounts/:id", async (
    99→    req: FastifyRequest<{ Params: { id: string } }>,
   100→    reply,
   101→  ) => {
   102→    const result = await removeAccount(req.params.id);
   103→    if (!result.success) {
   104→      reply.code(404);
   105→      return result;
   106→    }
   107→    return result;
   108→  });
   109→
   110→  // POST /api/accounts/:id/test — connectivity test
   111→  fastify.post("/api/accounts/:id/test", async (
   112→    req: FastifyRequest<{ Params: { id: string } }>,
   113→  ) => {
   114→    const result = await testAccount(req.params.id);
   115→    return result;
   116→  });
   117→}
